#include <bits/stdc++.h>

using namespace std;

int main() {
    int h, w, n;
    cin >> h >> w >> n;
    vector<pair<int, int>> coins;
    for (int i = 0; i < n; i++) {
        int r, c;
        cin >> r >> c;
        coins.emplace_back(r, c);
    }
    sort(coins.begin(), coins.end());
    vector<int> dp(n, 1e9), id(n, -1), pre(n);
    for (int i = 0; i < n; i++) {
        int it = upper_bound(dp.begin(), dp.end(), coins[i].second) - dp.begin();
        dp[it] = coins[i].second;
        id[it] = i;
        pre[i] = (it ? id[it - 1] : -1);
    }
    int m = n - 1;
    while (id[m] == -1) --m;
    vector<pair<int, int>> path = {{h, w}};
    int now = id[m];
    while (now != -1) {
        path.push_back(coins[now]);
        now = pre[now];
    }
    path.emplace_back(1, 1);
    reverse(path.begin(), path.end());
    string s;
    for (int i = 0; i < (int) path.size() - 1; i++) {
        int d = path[i + 1].first - path[i].first;
        int r = path[i + 1].second - path[i].second;
        while (d--) s.push_back('D');
        while (r--) s.push_back('R');
    }
    cout << m + 1 << '\n' << s << '\n';
}

#include <bits/stdc++.h>
using namespace std;

#include <atcoder/all>
using namespace atcoder;

using P = pair<int, int>;
P op(P x, P y) { return x.first > y.first ? x : y; }
P e() { return {0, -1}; }

int main()
{
    int h, w, n;
    cin >> h >> w >> n;
    vector<P> coins(n + 2);
    coins[0] = {0, 0};
    for (int i = 1; i <= n; i++)
    {
        int r, c;
        cin >> r >> c;
        coins[i] = {r - 1, c - 1};
    }
    coins[n + 1] = {h - 1, w - 1};
    n += 2;
    sort(coins.begin(), coins.end());

    vector<int> dp(n), prv(n);
    segtree<P, op, e> seg(w);
    for (int i = 0; i < n; i++)
    {
        int c = coins[i].second;
        auto p = seg.prod(0, c + 1);
        dp[i] = p.first + 1;
        prv[i] = p.second;
        if (seg.get(c).first < dp[i]) seg.set(c, {dp[i], i});
    }

    cout << (dp[n - 1] - 2) << "\n";

    vector<char> moves;
    for (int idx = n - 1; idx != 0; idx = prv[idx])
    {
        auto [x1, y1] = coins[idx];
        auto [x2, y2] = coins[prv[idx]];
        for (; x2 < x1; x1--) moves.push_back('D');
        for (; y2 < y1; y1--) moves.push_back('R');
    }
    reverse(moves.begin(), moves.end());
    for (auto c : moves) cout << c;
    cout << "\n";
}
